-- Load the checksum-verified HUD NSPIRE registry and require two distinct staff attestations before activation.
-- Source bundle SHA-256: 9758d7703e574eb3f0ab923b58dc9040cf5f6e7a671db2785ebd4ec7ebee6254

alter table public.pha_nspire_deficiency_standards
  alter column hcv_correction_hours drop not null;
alter table public.pha_nspire_deficiency_standards
  drop constraint if exists pha_nspire_deficiency_standards_hcv_correction_hours_check;
alter table public.pha_nspire_deficiency_standards
  add constraint pha_nspire_deficiency_standards_hcv_deadline_consistency
  check (
    (hcv_pass_fail='pass' and hcv_correction_hours is null)
    or (hcv_pass_fail='fail' and hcv_correction_hours is not null and hcv_correction_hours > 0)
  );

alter table public.pha_nspire_standard_releases
  add column if not exists expected_deficiency_count integer
    check (expected_deficiency_count is null or expected_deficiency_count > 0);

create table if not exists public.pha_nspire_release_attestations (
  id uuid primary key default gen_random_uuid(),
  release_id uuid not null references public.pha_nspire_standard_releases(id) on delete cascade,
  verifier_id uuid not null references auth.users(id),
  attested_sha256 text not null,
  attested_at timestamptz not null default now(),
  unique(release_id, verifier_id)
);

alter table public.pha_nspire_release_attestations enable row level security;
grant select on public.pha_nspire_release_attestations to authenticated;
grant all on public.pha_nspire_release_attestations to service_role;
create policy "Staff read NSPIRE release attestations"
  on public.pha_nspire_release_attestations for select to authenticated
  using (public.has_role(auth.uid(),'staff'));

do $$
declare
  rid uuid;
  loaded_standard_count integer;
  loaded_deficiency_count integer;
begin
  select id into rid
  from public.pha_nspire_standard_releases
  where release_key='HUD-NSPIRE-FINAL-STANDARDS';

  if rid is null then
    raise exception 'Controlled NSPIRE release is missing';
  end if;

  update public.pha_nspire_standard_releases
     set source_checksum='9758d7703e574eb3f0ab923b58dc9040cf5f6e7a671db2785ebd4ec7ebee6254',
         bundle_url='https://www.hud.gov/sites/dfiles/PIH/documents/NSPIRE-Standards-ALL-STANDARDS.zip',
         expected_standard_count=63,
         expected_deficiency_count=407,
         source_version='HUD current NSPIRE standards bundle — SHA-256 9758d7703e57',
         status='pending',
         verified_by=null,
         verified_at=null,
         activated_at=null,
         notes='Checksum-verified HUD bundle parsed into 407 actionable deficiency/location rows across 63 standards. One HUD Handrail N/A condition is excluded. Activation requires attestations from two distinct staff verifiers.',
         updated_at=now()
   where id=rid;

  if exists(
    select 1
    from public.pha_nspire_deficiency_standards s
    where s.release_id=rid
      and (
        s.active
        or s.source_status<>'pending_source'
        or exists(
          select 1 from public.pha_inspection_deficiencies d
          where d.nspire_standard_id=s.id
        )
      )
  ) then
    raise exception 'Existing NSPIRE rows are active, non-provisional, or referenced by inspection evidence';
  end if;

  -- Replace only the inactive, unreferenced provisional seed rows from the earlier
  -- fail-closed registry migration. Verified inspection evidence is never removed.
  delete from public.pha_nspire_deficiency_standards s
  where s.release_id=rid
    and s.active=false
    and s.source_status='pending_source'
    and not exists(
      select 1 from public.pha_inspection_deficiencies d
      where d.nspire_standard_id=s.id
    );

  insert into public.pha_nspire_deficiency_standards(
    release_id,standard_name,inspectable_area,deficiency_reference,deficiency_description,
    severity,correction_hours,hcv_correction_hours,hcv_pass_fail,source_url,
    source_version,source_status,effective_from,active,source_checksum
  )
  select
    rid,
    row_value->>0,
    row_value->>1,
    row_value->>2,
    row_value->>3,
    row_value->>4,
    (row_value->>5)::integer,
    nullif(row_value->>6,'')::integer,
    row_value->>7,
    'https://www.hud.gov/sites/dfiles/PIH/documents/NSPIRE-Standards-ALL-STANDARDS.zip#' || (row_value->>8),
    (row_value->>9) || ' — ' || (row_value->>10),
    'pending_source',
    (row_value->>10)::date,
    false,
    '9758d7703e574eb3f0ab923b58dc9040cf5f6e7a671db2785ebd4ec7ebee6254'
  from jsonb_array_elements($registry$[["Address And Signage","outside","Deficiency 1","ADDRESS, SIGNAGE, OR BUILDING IDENTIFICATION CODES ARE BROKEN, ILLEGIBLE, OR NOT VISIBLE.","moderate",720,720,"fail","NSPIRE-Standard-Address-and-Signage_20230811.pdf","V3.0","2023-08-11"],["Bathtub And Shower","unit","Deficiency 1","ONLY 1 BATHTUB OR SHOWER IS PRESENT AND IT IS INOPERABLE OR DOES NOT DRAIN.","severe",24,720,"fail","NSPIRE-Standard-Bathtub-and-Shower_20230811.pdf","V3.0","2023-08-11"],["Bathtub And Shower","inside","Deficiency 1","ONLY 1 BATHTUB OR SHOWER IS PRESENT AND IT IS INOPERABLE OR DOES NOT DRAIN.","low",1440,null,"pass","NSPIRE-Standard-Bathtub-and-Shower_20230811.pdf","V3.0","2023-08-11"],["Bathtub And Shower","unit","Deficiency 2","A BATHTUB OR SHOWER IS INOPERABLE OR DOES NOT DRAIN AND AT LEAST 1 BATHTUB OR SHOWER IS PRESENT ELSEWHERE THAT IS OPERATIONAL.","moderate",720,720,"fail","NSPIRE-Standard-Bathtub-and-Shower_20230811.pdf","V3.0","2023-08-11"],["Bathtub And Shower","inside","Deficiency 2","A BATHTUB OR SHOWER IS INOPERABLE OR DOES NOT DRAIN AND AT LEAST 1 BATHTUB OR SHOWER IS PRESENT ELSEWHERE THAT IS OPERATIONAL.","low",1440,null,"pass","NSPIRE-Standard-Bathtub-and-Shower_20230811.pdf","V3.0","2023-08-11"],["Bathtub And Shower","unit","Deficiency 3","BATHTUB COMPONENT OR SHOWER COMPONENT IS DAMAGED, INOPERABLE, OR MISSING SUCH THAT IT MAY LIMIT THE RESIDENT\u2019S ABILITY TO MAINTAIN PERSONAL HYGIENE.","moderate",720,720,"fail","NSPIRE-Standard-Bathtub-and-Shower_20230811.pdf","V3.0","2023-08-11"],["Bathtub And Shower","inside","Deficiency 3","BATHTUB COMPONENT OR SHOWER COMPONENT IS DAMAGED, INOPERABLE, OR MISSING SUCH THAT IT MAY LIMIT THE RESIDENT\u2019S ABILITY TO MAINTAIN PERSONAL HYGIENE.","low",1440,null,"pass","NSPIRE-Standard-Bathtub-and-Shower_20230811.pdf","V3.0","2023-08-11"],["Bathtub And Shower","unit","Deficiency 4","BATHTUB COMPONENT OR SHOWER COMPONENT IS DAMAGED, INOPERABLE, OR MISSING AND IT DOES NOT LIMIT THE RESIDENT\u201