it","Deficiency 1","WINDOW WILL NOT OPEN OR STAY OPEN.","moderate",720,720,"fail","NSPIRE-Standard-Window_20230811.pdf","V3.0","2023-08-11"],["Window","inside","Deficiency 1","WINDOW WILL NOT OPEN OR STAY OPEN.","low",1440,null,"pass","NSPIRE-Standard-Window_20230811.pdf","V3.0","2023-08-11"],["Window","unit","Deficiency 2","WINDOW CANNOT BE SECURED.","moderate",720,720,"fail","NSPIRE-Standard-Window_20230811.pdf","V3.0","2023-08-11"],["Window","inside","Deficiency 2","WINDOW CANNOT BE SECURED.","low",1440,null,"pass","NSPIRE-Standard-Window_20230811.pdf","V3.0","2023-08-11"],["Window","unit","Deficiency 3","WINDOW WILL NOT CLOSE.","severe",24,720,"fail","NSPIRE-Standard-Window_20230811.pdf","V3.0","2023-08-11"],["Window","inside","Deficiency 3","WINDOW WILL NOT CLOSE.","moderate",720,720,"fail","NSPIRE-Standard-Window_20230811.pdf","V3.0","2023-08-11"],["Window","unit","Deficiency 4","WINDOW COMPONENT IS DAMAGED OR MISSING AND THE WINDOW IS NOT FUNCTIONALLY ADEQUATE .","moderate",720,720,"fail","NSPIRE-Standard-Window_20230811.pdf","V3.0","2023-08-11"],["Window","inside","Deficiency 4","WINDOW COMPONENT IS DAMAGED OR MISSING AND THE WINDOW IS NOT FUNCTIONALLY ADEQUATE .","moderate",720,720,"fail","NSPIRE-Standard-Window_20230811.pdf","V3.0","2023-08-11"]]$registry$::jsonb) as source_rows(row_value)
  on conflict (standard_name,inspectable_area,deficiency_reference,source_version)
  do update set
    release_id=excluded.release_id,
    deficiency_description=excluded.deficiency_description,
    severity=excluded.severity,
    correction_hours=excluded.correction_hours,
    hcv_correction_hours=excluded.hcv_correction_hours,
    hcv_pass_fail=excluded.hcv_pass_fail,
    source_url=excluded.source_url,
    source_status='pending_source',
    effective_from=excluded.effective_from,
    active=false,
    source_checksum=excluded.source_checksum,
    updated_at=now();

  select count(distinct standard_name),count(*)
    into loaded_standard_count,loaded_deficiency_count
  from public.pha_nspire_deficiency_standards
  where release_id=rid;

  if loaded_standard_count<>63 or loaded_deficiency_count<>407 then
    raise exception 'NSPIRE controlled registry count mismatch: standards %, deficiencies %',
      loaded_standard_count,loaded_deficiency_count;
  end if;

  update public.pha_nspire_standard_releases
     set imported_standard_count=loaded_standard_count,
         imported_deficiency_count=loaded_deficiency_count,
         import_completed_at=now(),
         updated_at=now()
   where id=rid;

  insert into public.pha_nspire_source_artifacts(
    release_id,artifact_name,artifact_type,source_url,sha256,import_status,parsed_row_count
  )
  values(
    rid,'NSPIRE-Standards-ALL-STANDARDS.zip','bundle_zip',
    'https://www.hud.gov/sites/dfiles/PIH/documents/NSPIRE-Standards-ALL-STANDARDS.zip',
    '9758d7703e574eb3f0ab923b58dc9040cf5f6e7a671db2785ebd4ec7ebee6254','parsed',407
  )
  on conflict (release_id,artifact_name) do update set
    source_url=excluded.source_url,
    sha256=excluded.sha256,
    import_status='parsed',
    parsed_row_count=407,
    verified_by=null,
    verified_at=null,
    updated_at=now();
end $$;

create or replace function public.attest_and_activate_pha_nspire_release(
  target_release_id uuid,
  expected_sha256 text
)
returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare
  caller_id uuid:=auth.uid();
  release_row public.pha_nspire_standard_releases%rowtype;
  standard_count integer;
  deficiency_count integer;
  attestation_count integer;
  artifact_ok boolean;
  is_activated boolean:=false;
begin
  if caller_id is null or not public.has_role(caller_id,'staff') then
    raise exception 'Staff authority required to attest to NSPIRE source integrity';
  end if;

  select * into release_row
  from public.pha_nspire_standard_releases
  where id=target_release_id
  for update;

  if not found then raise exception 'NSPIRE standards release not found'; end if;
  if expected_sha256 is distinct from release_row.source_checksum
     or expected_sha256<>'9758d7703e574eb3f0ab923b58dc9040cf5f6e7a671db2785ebd4ec7ebee6254' then
    raise exception 'NSPIRE checksum does not match the controlled HUD bundle';
  end if;

  select count(distinct standard_name),count(*)
    into standard_count,deficiency_count
  from public.pha_nspire_deficiency_standards
  where release_id=target_release_id;

  if standard_count<>release_row.expected_standard_count
     or deficiency_count<>release_row.expected_deficiency_count then
    raise exception 'NSPIRE imported counts do not match the controlled manifest';
  end if;

  select exists(
    select 1 from public.pha_nspire_source_artifacts
    where release_id=target_release_id
      and artifact_type='bundle_zip'
      and sha256=expected_sha256
      and import_status in ('parsed','verified')
      and parsed_row_count=release_row.expected_deficiency_count
  ) into artifact_ok;

  if not artifact_ok then
    raise exception 'Parsed HUD bundle artifact is incomplete or has the wrong checksum';
  end if;

  insert into public.pha_nspire_release_attestations(
    release_id,verifier_id,attested_sha256
  )
  values(target_release_id,caller_id,expected_sha256)
  on conflict (release_id,verifier_id) do update set
    attested_sha256=excluded.attested_sha256,
    attested_at=now();

  select count(distinct verifier_id) into attestation_count
  from public.pha_nspire_release_attestations
  where release_id=target_release_id and attested_sha256=expected_sha256;

  if attestation_count>=2 then
    update public.pha_nspire_source_artifacts
       set import_status='verified',verified_by=caller_id,verified_at=now(),updated_at=now()
     where release_id=target_release_id and artifact_type='bundle_zip' and sha256=expected_sha256;
    update public.pha_nspire_standard_releases
       set verified_by=caller_id,verified_at=now(),updated_at=now()
     where id=target_release_id;
    perform public.activate_pha_nspire_standard_release(target_release_id);
    is_activated:=true;
  end if;

  return jsonb_build_object(
    'release_id',target_release_id,
    'attestations',attestation_count,
    'required_attestations',2,
    'activated',is_activated
  );
end $$;

grant execute on function public.attest_and_activate_pha_nspire_release(uuid,text) to authenticated;
